#!/usr/bin/env python3
# Minimal cBPF disassembler + interpreter for a seccomp filter.
# Decodes struct sock_filter records (code u16, jt u8, jf u8, k u32) and runs
# each candidate syscall number through the program to find which are allowed.
import struct, sys

data = open(sys.argv[1] if len(sys.argv) > 1 else 'filter.bpf', 'rb').read()
assert len(data) % 8 == 0, 'bad filter length'
insns = [struct.unpack_from('<HBBI', data, i) for i in range(0, len(data), 8)]

for idx, (code, jt, jf, k) in enumerate(insns):
    if code == 0x20:   print(f'{idx:2}: ld [off={k}]')
    elif code == 0x15: print(f'{idx:2}: jeq {k:#x} ? +{jt} : +{jf}')
    elif code == 0x06: print(f'{idx:2}: ret {k:#x}')
    else:              print(f'{idx:2}: (code {code:#x})')

KILL, ALLOW = 0x00000000, 0x7fff0000
def verdict(nr):
    # struct seccomp_data: nr at off 0, arch at off 4
    mem = {0: nr, 4: 0xC000003E}
    A = 0
    pc = 0
    while pc < len(insns):
        code, jt, jf, k = insns[pc]
        if code == 0x20:      # ld [k]
            A = mem.get(k, 0); pc += 1
        elif code == 0x15:    # jeq k
            pc += (jt + 1) if A == k else (jf + 1)
        elif code == 0x06:    # ret k
            return k
        else:
            return None
    return None

allowed = [n for n in range(0, 512) if verdict(n) == ALLOW]
print('allowed syscalls:', ','.join(str(n) for n in allowed))
